}
function netHubGiftTake(peer,m,fr){
  var H=NET.hg||(NET.hg={}), key=netClean(m.k,32), it=ITEMS[key], nm=hubGiftName(fr), go, gi, ix;
  if(m.op==='offer'){
    if(!it) return 'bad';
